//! The TURZX V1.x USB panels' commands, as devices/turzx_usb.py builds them: one 512-byte packet
//! each, 500 bytes of plain text ([0] the command, [2..4] the magic 1A 6D, [4..8] milliseconds
//! since local midnight, little endian, [8..] the arguments) DES-CBC encrypted with key = IV =
//! "slv3tuzx" (zero padded to 504), bytes 510 and 511 the trailer A1 1A; a payload follows the
//! packet in the same transfer.

use cbc::cipher::{BlockEncryptMut, KeyIvInit};

pub const KEY: &[u8; 8] = b"slv3tuzx";
pub const MAGIC: [u8; 2] = [0x1a, 0x6d];
pub const TRAILER: [u8; 2] = [0xa1, 0x1a];
pub const PACKET: usize = 512;
/// The most arguments a packet takes.
pub const MAX_ARGS: usize = 492;

type Encryptor = cbc::Encryptor<des::Des>;

/// The packet of command `cmd` with its `args`, stamped `ms` milliseconds after local midnight.
pub fn packet(cmd: u8, args: &[u8], ms: u32) -> Result<[u8; PACKET], String> {
    if args.len() > MAX_ARGS {
        return Err(format!("the arguments of command {cmd} are too long"));
    }
    let mut plain = [0u8; 504];
    plain[0] = cmd;
    plain[2..4].copy_from_slice(&MAGIC);
    plain[4..8].copy_from_slice(&ms.to_le_bytes());
    plain[8..8 + args.len()].copy_from_slice(args);
    let mut cipher = Encryptor::new(KEY.into(), KEY.into());
    for block in plain.chunks_exact_mut(8) {
        cipher.encrypt_block_mut(block.into());
    }
    let mut out = [0u8; PACKET];
    out[..504].copy_from_slice(&plain);
    out[510..].copy_from_slice(&TRAILER);
    Ok(out)
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use cbc::cipher::BlockDecryptMut;

    /// The plain text of a packet (turzx_usb.decode_packet): checks its trailer and magic.
    pub(crate) fn decoded(packet: &[u8]) -> [u8; 504] {
        assert_eq!(&packet[510..512], &TRAILER, "not a command packet");
        let mut plain = [0u8; 504];
        plain.copy_from_slice(&packet[..504]);
        let mut cipher = cbc::Decryptor::<des::Des>::new(KEY.into(), KEY.into());
        for block in plain.chunks_exact_mut(8) {
            cipher.decrypt_block_mut(block.into());
        }
        assert_eq!(plain[2..4], MAGIC, "bad magic");
        plain
    }

    fn hex(text: &str) -> Vec<u8> {
        (0..text.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
            .collect()
    }

    /// Packets as the Python driver builds them (turzx_usb.build_packet), byte for byte.
    #[test]
    fn packets_are_the_python_drivers() {
        let vectors: &[(u8, &str, u32, &str)] = &[
        (10, "", 80000123, ""),
        (14, "38", 80000123, ""),
        (15, "3c", 80000123, ""),
        (17, "", 80000123, ""),
        (110, "00000016000000007573722f646174612f7374616e6462792e68323634", 80000123, ""),
        (121, "000004d2", 80000123, ""),
        (122, "", 80000123, ""),
        (123, "", 80000123, ""),
        ];
        for (cmd, args, ms, want) in vectors {
            assert_eq!(
                packet(*cmd, &hex(args), *ms).unwrap().to_vec(),
                hex(want),
                "command {cmd}"
            );
        }
        assert!(packet(10, &[0; 493], 0).is_err());
    }
}
